import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form, ButtonGroup } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { bpmnAPI, logistikAPI } from '../../services/api';

const RoomBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [filteredBookings, setFilteredBookings] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [selectedRoomId, setSelectedRoomId] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');

  useEffect(() => {
    fetchBookings();
  }, []);

  useEffect(() => {
    filterBookings();
  }, [bookings, filter]);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching room bookings...');
      
      const [bookingsRes, roomsRes] = await Promise.all([
        bpmnAPI.getValidatedRequestsForLogistik(),
        logistikAPI.getRooms()
      ]);
      
      console.log('✅ Bookings response:', bookingsRes);
      
      // Handle bookings data
      let bookingsData = [];
      if (bookingsRes.data && bookingsRes.data.success && bookingsRes.data.data) {
        bookingsData = bookingsRes.data.data;
      } else if (Array.isArray(bookingsRes.data)) {
        bookingsData = bookingsRes.data;
      }

      // Handle rooms data
      let roomsData = [];
      if (roomsRes.data && roomsRes.data.success && roomsRes.data.data) {
        roomsData = roomsRes.data.data;
      } else if (Array.isArray(roomsRes.data)) {
        roomsData = roomsRes.data;
      }

      console.log('📋 Final bookings:', bookingsData.length);
      setBookings(bookingsData);
      setRooms(roomsData.filter(r => r.is_active));
      
    } catch (error) {
      console.error('❌ Error fetching bookings:', error);
      toast.error('Gagal memuat data bookings: ' + (error.response?.data?.message || error.message));
    } finally {
      setLoading(false);
    }
  };

  const filterBookings = () => {
    if (filter === 'all') {
      setFilteredBookings(bookings);
    } else {
      const filtered = bookings.filter(booking => {
        const status = booking.room_status || booking.status;
        return status === filter;
      });
      setFilteredBookings(filtered);
    }
  };

  const handleApprove = (booking) => {
    setSelectedBooking(booking);
    setShowApproveModal(true);
  };

  const handleReject = (booking) => {
    setSelectedBooking(booking);
    setShowRejectModal(true);
  };

  const submitApprove = async (requestId, roomId) => {
    try {
      const data = {
        action: 'approve'
      };
      if (roomId) {
        data.room_id = roomId;
        data.notes = `Ruangan disetujui oleh logistik`;
      }
      
      await bpmnAPI.logistikApproveRoom(requestId, data);
      toast.success('✅ Request berhasil disetujui!');
      
      fetchBookings();
      setShowApproveModal(false);
      setSelectedRoomId('');
    } catch (error) {
      console.error('Error approving request:', error);
      toast.error('Gagal menyetujui request: ' + (error.response?.data?.message || error.message));
    }
  };

  const submitReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Alasan penolakan harus diisi');
      return;
    }

    try {
      await bpmnAPI.logistikRejectRoom(selectedBooking.id, {
        action: 'reject',
        notes: rejectionReason
      });
      toast.success('✅ Request berhasil ditolak!');

      fetchBookings();
      setShowRejectModal(false);
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting request:', error);
      toast.error('Gagal menolak request: ' + (error.response?.data?.message || error.message));
    }
  };

  const getStatusBadge = (booking) => {
    const status = booking.room_status || booking.status;
    const variants = {
      pending: 'warning',
      approved: 'success', 
      rejected: 'danger'
    };
    
    return <Badge bg={variants[status] || 'secondary'}>{status?.toUpperCase() || 'UNKNOWN'}</Badge>;
  };

  const getRequestTypeBadge = (type) => {
    const variants = {
      room: 'success',
      zoom: 'primary',
      both: 'warning'
    };
    
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom', 
      both: 'Ruangan + Zoom'
    };
    
    return <Badge bg={variants[type] || 'secondary'}>{labels[type] || type}</Badge>;
  };

  if (loading) {
    return (
      <Container fluid className="py-4">
        <div className="text-center">
          <div className="spinner-border" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      </Container>
    );
  }

  return (
    <Container fluid className="py-4">
      <Row className="mb-4">
        <Col>
          <h2 className="mb-0">
            <i className="fas fa-calendar-check me-2 text-success"></i>
            Booking Ruangan
          </h2>
          <p className="text-muted">Kelola semua booking ruangan yang memerlukan persetujuan</p>
        </Col>
      </Row>

      <Row>
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-white border-bottom">
              <Row className="align-items-center">
                <Col>
                  <h5 className="mb-0">Filter Status:</h5>
                </Col>
                <Col xs="auto">
                  <ButtonGroup>
                    <Button
                      variant={filter === 'all' ? 'success' : 'outline-success'}
                      size="sm"
                      onClick={() => setFilter('all')}
                    >
                      Semua Status
                    </Button>
                    <Button
                      variant={filter === 'pending' ? 'warning' : 'outline-warning'}
                      size="sm"  
                      onClick={() => setFilter('pending')}
                    >
                      Pending
                    </Button>
                    <Button
                      variant={filter === 'approved' ? 'success' : 'outline-success'}
                      size="sm"
                      onClick={() => setFilter('approved')}
                    >
                      Approved
                    </Button>
                    <Button
                      variant={filter === 'rejected' ? 'danger' : 'outline-danger'}
                      size="sm"
                      onClick={() => setFilter('rejected')}
                    >
                      Rejected
                    </Button>
                  </ButtonGroup>
                </Col>
              </Row>
            </Card.Header>
            <Card.Body className="p-0">
              {filteredBookings.length > 0 ? (
                <Table responsive className="mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>User</th>
                      <th>Judul</th>
                      <th>Tanggal</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Kapasitas</th>
                      <th>Ruangan</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredBookings.map((booking) => (
                      <tr key={booking.id}>
                        <td>
                          <div>
                            <strong>{booking.user_name}</strong>
                            <br />
                            <small className="text-muted">{booking.user_email}</small>
                          </div>
                        </td>
                        <td>
                          <strong>{booking.title}</strong>
                          <br />
                          <small className="text-muted">{booking.purpose}</small>
                        </td>
                        <td>{new Date(booking.date).toLocaleDateString('id-ID')}</td>
                        <td>
                          {booking.start_time} - {booking.end_time}
                        </td>
                        <td>
                          {getRequestTypeBadge(booking.request_type)}
                        </td>
                        <td>{booking.capacity} orang</td>
                        <td>
                          {booking.room_name ? (
                            <Badge bg="info">{booking.room_name}</Badge>
                          ) : (
                            <Badge bg="secondary">Belum dialokasi</Badge>
                          )}
                        </td>
                        <td>{getStatusBadge(booking)}</td>
                        <td>
                          <div className="d-flex gap-1">
                            <Button
                              variant="outline-info"
                              size="sm"
                              onClick={() => {
                                setSelectedBooking(booking);
                                setShowDetailModal(true);
                              }}
                              title="View Details"
                            >
                              <i className="fas fa-eye"></i>
                            </Button>
                            
                            {(booking.room_status === 'pending' || booking.status === 'pending') && 
                             (booking.request_type === 'room' || booking.request_type === 'both') && (
                              <>
                                <Button
                                  variant="success"
                                  size="sm"
                                  onClick={() => handleApprove(booking)}
                                  title="Approve Request"
                                >
                                  <i className="fas fa-check"></i>
                                </Button>
                                <Button
                                  variant="danger"
                                  size="sm"
                                  onClick={() => handleReject(booking)}
                                  title="Reject Request"
                                >
                                  <i className="fas fa-times"></i>
                                </Button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-5">
                  <i className="fas fa-inbox fa-4x text-muted mb-3"></i>
                  <h5 className="text-muted">
                    {filter === 'all' ? 'Tidak ada booking' : `Tidak ada booking dengan status ${filter}`}
                  </h5>
                  <p className="text-muted">Booking akan muncul di sini ketika ada request yang perlu diproses.</p>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Detail Modal */}
      <Modal show={showDetailModal} onHide={() => setShowDetailModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Detail Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <Row>
              <Col md={6}>
                <h6>Informasi Request</h6>
                <ul className="list-unstyled">
                  <li><strong>ID:</strong> {selectedBooking.id}</li>
                  <li><strong>Judul:</strong> {selectedBooking.title}</li>
                  <li><strong>Purpose:</strong> {selectedBooking.purpose}</li>
                  <li><strong>Jenis:</strong> {getRequestTypeBadge(selectedBooking.request_type)}</li>
                  <li><strong>Status:</strong> {getStatusBadge(selectedBooking)}</li>
                </ul>
              </Col>
              <Col md={6}>
                <h6>Informasi Waktu & User</h6>
                <ul className="list-unstyled">
                  <li><strong>User:</strong> {selectedBooking.user_name}</li>
                  <li><strong>Email:</strong> {selectedBooking.user_email}</li>
                  <li><strong>Tanggal:</strong> {new Date(selectedBooking.date).toLocaleDateString('id-ID')}</li>
                  <li><strong>Waktu:</strong> {selectedBooking.start_time} - {selectedBooking.end_time}</li>
                  <li><strong>Kapasitas:</strong> {selectedBooking.capacity} orang</li>
                </ul>
              </Col>
              <Col md={12}>
                <h6>Informasi Ruangan & Zoom</h6>
                <ul className="list-unstyled">
                  <li><strong>Ruangan:</strong> {selectedBooking.room_name || 'Belum dialokasi'}</li>
                  <li><strong>Zoom Link:</strong> {selectedBooking.zoom_link || 'Belum ada'}</li>
                  <li><strong>Zoom Account:</strong> {selectedBooking.zoom_account_name || 'Belum ada'}</li>
                </ul>
              </Col>
              {(selectedBooking.room_notes || selectedBooking.zoom_notes) && (
                <Col md={12}>
                  <h6>Catatan</h6>
                  {selectedBooking.room_notes && (
                    <div className="alert alert-info">
                      <strong>Catatan Ruangan:</strong> {selectedBooking.room_notes}
                    </div>
                  )}
                  {selectedBooking.zoom_notes && (
                    <div className="alert alert-primary">
                      <strong>Catatan Zoom:</strong> {selectedBooking.zoom_notes}
                    </div>
                  )}
                </Col>
              )}
            </Row>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDetailModal(false)}>
            Tutup
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Approve Modal */}
      <Modal show={showApproveModal} onHide={() => setShowApproveModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Approve Room Request</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <>
              <div className="alert alert-info">
                <i className="fas fa-info-circle me-2"></i>
                <strong>Logistik:</strong> Pilih ruangan yang sesuai untuk request ini.
              </div>
              
              <p>Detail request:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedBooking.title}</li>
                <li><strong>User:</strong> {selectedBooking.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedBooking.date).toLocaleDateString('id-ID')}</li>
                <li><strong>Waktu:</strong> {selectedBooking.start_time} - {selectedBooking.end_time}</li>
                <li><strong>Kapasitas:</strong> {selectedBooking.capacity} orang</li>
              </ul>

              <Form.Group className="mt-3">
                <Form.Label>Pilih Ruangan:</Form.Label>
                <Form.Select
                  value={selectedRoomId}
                  onChange={(e) => setSelectedRoomId(e.target.value)}
                  required
                >
                  <option value="">-- Pilih Ruangan --</option>
                  {rooms.filter(r => r.capacity >= selectedBooking.capacity).map(room => (
                    <option key={room.id} value={room.id}>
                      {room.room_name || room.name} (Kapasitas: {room.capacity})
                    </option>
                  ))}
                </Form.Select>
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowApproveModal(false)}>
            Batal
          </Button>
          <Button 
            variant="success" 
            onClick={() => submitApprove(selectedBooking?.id, selectedRoomId || null)}
            disabled={!selectedRoomId}
          >
            <i className="fas fa-check me-2"></i>
            Approve
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Reject Modal */}
      <Modal show={showRejectModal} onHide={() => setShowRejectModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Reject Request</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <>
              <p>Anda akan menolak request berikut:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedBooking.title}</li>
                <li><strong>User:</strong> {selectedBooking.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedBooking.date).toLocaleDateString('id-ID')}</li>
              </ul>
              
              <Form.Group className="mt-3">
                <Form.Label>Alasan Penolakan <span className="text-danger">*</span></Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  placeholder="Masukkan alasan penolakan..."
                  required
                />
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowRejectModal(false)}>
            Batal
          </Button>
          <Button 
            variant="danger" 
            onClick={submitReject}
            disabled={!rejectionReason.trim()}
          >
            <i className="fas fa-times me-2"></i>
            Reject
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default RoomBookings;
